<script setup>
import {ref,computed,onMounted,onBeforeUnmount,watch} from 'vue'
import {missions} from './missions.js'
import {state} from './store.js'
import {missionExamples} from './mission-examples.js'
import {DRAFT_KEY,normalizeDrafts} from './investigation-drafts.js'
import EvidenceLens from './EvidenceLens.vue'
const selected=ref(0),request=ref({...missions[0].request}),logs=ref([]),hypothesis=ref(''),notes=ref(''),hint=ref(0),revealed=ref(false),saved=ref(false),draftError=ref(''),draftReady=ref(false),inspected=ref(null)
let activeIndex=0,restoring=false,timer,drafts={}
const mission=computed(()=>missions[selected.value])
const observations=computed(()=>new Set(logs.value.map(l=>l.evidence).filter(Boolean)))
const demonstrated=computed(()=>mission.value.id==='media-chain'?observations.value.has('discovery')&&observations.value.has('internal-fetch'):observations.value.size>0)
const canSave=computed(()=>demonstrated.value&&hypothesis.value.trim().length>=15&&notes.value.trim().length>=25)
const snapshots=computed(()=>logs.value.map(log=>({id:log.index,values:{...log.request},safe:false,result:log,label:'Recorded request'})).reverse())
const currentSnapshot=computed(()=>snapshots.value.find(s=>s.id===inspected.value)||snapshots.value[0]||null)
const fields=[{key:'session',label:'Session / actor'},{key:'path',label:'Path'},{key:'input',label:'Input value / body'}]
function execute(m,r){try{const known=m.routes.some(route=>route.split(' ')[1].split('?')[0]===r.path.split('?')[0]);return known?m.run(r):{status:'error',trace:'No route matched the request.',output:'404: route absent from this workspace',explanation:'Compare the requested path with the observed route inventory.'}}catch(e){return {status:'error',trace:'Request did not reach the modeled operation.',output:e.message,explanation:'Check the input type and request inventory.'}}}
function persist(){clearTimeout(timer);if(!draftReady.value||restoring)return;drafts[missions[activeIndex].id]={request:{...request.value},requests:logs.value.map(l=>l.request).slice(-20),hypothesis:hypothesis.value,notes:notes.value,hint:hint.value,revealed:revealed.value};try{localStorage.setItem(DRAFT_KEY,JSON.stringify(drafts));draftError.value=''}catch{draftError.value='Draft storage is unavailable. Save or copy your notes before closing this page.'}}
function restore(index){restoring=true;activeIndex=index;const m=missions[index],draft=drafts[m.id];request.value={...(draft?.request||m.request)};logs.value=(draft?.requests||[]).map((r,i)=>({...execute(m,r),request:{...r},index:i+1}));hypothesis.value=draft?.hypothesis||'';notes.value=draft?.notes||'';hint.value=draft?.hint||0;revealed.value=draft?.revealed||false;saved.value=false;inspected.value=null;restoring=false}
function change(){persist();restore(selected.value)}
function send(){const r={session:request.value.session,path:request.value.path,input:request.value.input};const index=(logs.value.at(-1)?.index||0)+1;logs.value=[...logs.value,{...execute(mission.value,r),request:r,index}].slice(-20);inspected.value=index;saved.value=false}
function useExample(example){request.value={session:example.session||mission.value.request.session,path:example.path||mission.value.request.path,input:example.input};send()}
function save(){if(!canSave.value)return;state.missions[mission.value.id]=true;state.notes['mission:'+mission.value.id]=`Hypothesis: ${hypothesis.value}\n\nEvidence and limits:\n${notes.value}\n\nRecorded requests:\n${logs.value.map(l=>`${l.request.path}: ${l.request.input}\n${l.output}`).join('\n\n')}`.slice(0,20000);saved.value=true;persist()}
watch([request,logs,hypothesis,notes,hint,revealed],()=>{if(restoring||!draftReady.value)return;clearTimeout(timer);timer=setTimeout(persist,250)},{deep:true,flush:'sync'})
onMounted(()=>{try{drafts=normalizeDrafts(JSON.parse(localStorage.getItem(DRAFT_KEY)||'{}'))}catch{drafts={};draftError.value='An old draft could not be restored. Your checked progress is unchanged.'}draftReady.value=true;restore(0);window.addEventListener('pagehide',persist)})
onBeforeUnmount(()=>{persist();clearTimeout(timer);window.removeEventListener('pagehide',persist)})
</script>
<template><section class="investigation-desk"><div class="desk-intro"><label class="select-label">Fictional workspace<select v-model="selected" @change="change"><option v-for="(m,i) in missions" :value="i" :key="m.id">{{m.title}}{{state.missions[m.id]?' · evidence recorded':''}}</option></select></label><span class="eyebrow">LOCAL INVESTIGATION · NO LAB TARGET</span></div><h2>{{mission.title}}</h2><p class="case-scene">{{mission.scene}}</p><p class="draft-save-status" :class="{'draft-warning':draftError}">{{draftError||'Drafts stay in this browser. Saved investigation records are included in your progress backup.'}}</p><details class="desk-inventory"><summary>Observed routes</summary><code v-for="route in mission.routes" :key="route">{{route}}</code></details><div class="desk-workspace"><form @submit.prevent="send"><h3>Replay a request</h3><div class="desk-ready"><span>Ready requests · click to try</span><div class="input-examples"><button v-for="example in missionExamples[mission.id]" :key="example.label" type="button" :title="example.input" @click="useExample(example)">{{example.label}}</button></div></div><label for="desk-session">Session / actor</label><input id="desk-session" v-model="request.session" :readonly="mission.id!=='receipts'" maxlength="80"><label for="desk-path">Path</label><input id="desk-path" v-model="request.path" maxlength="400"><label for="desk-input">Input value / body</label><textarea id="desk-input" v-model="request.input" rows="3" maxlength="3000" spellcheck="false"></textarea><button class="button primary" type="submit">Send to local fixture →</button><p class="fine-print">Ready requests are optional starting points. You can edit any input and build your own comparison.</p></form><div class="desk-evidence"><EvidenceLens v-if="currentSnapshot" :context="mission.id" :snapshot="currentSnapshot" :baseline="snapshots.at(-1)" :history="snapshots" :fields="fields" baseline-label="Earliest retained request"/><div class="desk-log"><h3>Evidence log <span>{{logs.length}}</span></h3><p class="fine-print">The latest 20 requests are kept in this draft.</p><p v-if="!logs.length" class="muted">Send a baseline first. The visual inspector and evidence log will appear here.</p><details v-for="log in [...logs].reverse()" :key="log.index" :open="log.index===(inspected??logs.at(-1)?.index)"><summary>Request {{log.index}} · {{log.request.path}}</summary><button class="quiet-button inspect-request" @click="inspected=log.index">Visualize request #{{log.index}} →</button><strong>Request input</strong><pre>{{log.request.input}}</pre><strong>Observation</strong><pre>{{log.output}}</pre><details class="teaching-trace"><summary>Reveal teaching trace</summary><pre>{{log.trace}}</pre><p>{{log.explanation}}</p></details></details></div></div></div><div class="desk-notebook"><h3>Make your reasoning inspectable.</h3><label for="desk-hypothesis">What boundary are you testing?</label><textarea id="desk-hypothesis" v-model="hypothesis" maxlength="3000" rows="2" placeholder="I think this service trusts…"></textarea><label for="desk-notes">Your control, evidence, alternative explanation, and proposed fix</label><textarea id="desk-notes" v-model="notes" maxlength="10000" rows="4" placeholder="What changed? What did you observe? What does it prove—and what remains unproven?"></textarea><button class="button primary" :disabled="!canSave" @click="save">Save investigation record</button><p class="fine-print" role="status">{{saved?'Record saved with your notes. Revisit it and challenge your explanation.':demonstrated?'The fixture observed a relevant boundary effect. Explain it before saving.':'No relevant boundary effect has been demonstrated yet. Keep your baseline and test one hypothesis.'}}</p></div><details class="desk-help"><summary>Need a nudge?</summary><p v-if="hint===0">Start with a normal request. Inspect the session, object or path, parser, and any server-side request. Write the observation you expect before changing one field.</p><p v-else>{{mission.hypothesis}}. What two requests would distinguish correct enforcement from misplaced trust?</p><button v-if="hint===0" class="quiet-button" @click="hint++">Focus the next hypothesis →</button><button class="quiet-button" @click="revealed=!revealed">{{revealed?'Hide':'Reveal'}} related learning →</button><a v-if="revealed" class="button" :href="`#/learn/${mission.module}/0`">Study the related mechanism ↗</a></details><p class="fine-print">Recording evidence is not automatic grading of your prose or proof of readiness for every CTF. These workspaces are separate from your Academy lab completion.</p></section></template>
